sealed interface Node permits Leaf, Branch {}
record Leaf(String text) implements Node {}
record Branch(List<Node> kids) implements Node {}
record Frame(Node parent, int index) {}                      // one hole per level
record Loc(Node focus, List<Frame> path) {}
static Loc up(Loc l) {                                       // rebuild the parent once
    var f = l.path().getLast();
    if (!(f.parent() instanceof Branch b)) throw new IllegalStateException("at root");
    var kids = new ArrayList<>(b.kids());
    kids.set(f.index(), l.focus());
    return new Loc(new Branch(List.copyOf(kids)), List.copyOf(l.path().subList(0, l.path().size() - 1)));
}

